reactiveclass Counter (Env env, Client client1, Client client2) {
	knownrebecs {
		Env env;
		Client client1;
		Client client2;
	}
	statevars {
		int count;
	}

	Counter() {
		count = 0;
	}

	msgsrv initial() {
		// no initial actions
	}

	msgsrv Increment(int senderId) {
		count = count + 1;
		env.printInt(count);
